INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66478916', 66478916, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN PENYUSUNAN REKOMENDASI KEBIJAKAN EVALUASI DAN PEMANTAUAN PROGRAM MAKAN BERGIZI GRATIS (MBG) 1', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 78000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Melakukan telaah regulasi, literatur review, serta pengumpulan data kualitatif dari stakeholder yang relevan 2. Menyusun policy brief/ buku dokumentasi rekomendasi kebijakan dari hasil kajian, pemantauan, dan evaluasi yang berkaitan dengan dampak gizi dan kesehatan masyarakat program MBG 3. Menyusun pers release dan narasi kegiatan strategis tim koordinasi strategis program MBG untuk komunikasi media kepada masyarakat luas', '1. Pendidikan minimal S2 di bidang Gizi/Kesehatan Masyarakat/ Ekonomi Kesehatan/ Kebijakan Publik. Dibuktikan dengan Ijazah. 2. Memiliki pengalaman kerja minimal 9 tahun pada bidang gizi/ kesehatan masyarakat/ kebijakan publik/ sosial/kemiskinan/ kesejahteraan sosial/pendidikan. Dibuktikan dengan surat keterangan kerja/kontrak kerja 3. Memiliki pemahaman/ pengalaman di bidang kebijakan gizi/ kesehatan masyarakat/ sosial/ kemiskinan/ pemberdayaan masyarakat/ kesejahteraan sosial. Dibuktikan dengan hasil pekerjaan/ paper/ karya ilmiah/ policy brief. 4. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak. 5. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak. 6. Memiliki pekerjaan sejenis bidang kesehatan/ kebijakan publik/ analis data kesehatan/ kebijakan gizi masyarakat/ kesehatan masyarakat/ sosial/ kemiskinan/ kesejahteraan sosial/ pendidikan. 7. Mempunyai status valid keterangan wajib pajak berdasarkan hasil konfirmasi status wajib pajak. 8. Memiliki nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran. 9. Diutamakan Konsultan dalam negeri yang dibuktikan dengan identitas kewarganegaraan Indonesia sebagai Kartu Tanda Penduduk', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2770311);
