INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66478910', 66478910, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN PENYUSUNAN REKOMENDASI KEBIJAKAN PEMANTAUAN DAN EVALUASI TATA KELOLA PROGRAM MAKAN BERGIZI GRATIS TAHUN 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 60000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Mengidentifikasi isu-isu strategis dalam implementasi MBG pada aspek intervensi gizi dan kesehatan yang berkelanjutan, Mengumpulkan data kuantitatif dan kualitatif yang berkaitan dengan isu gizi dan kesehatan masyarakat dalam program MBG, Mengembangkan analisis dan rekomendasi kebijakan yang komprehensif dan sejalan dengan kebijakan gizi dan kesehatan secara luas, Menyusun policy brief, laporan, dan bahan paparan, Memastikan kegiatan monev program MBG berjalan sesuai timeline dan rancangan awal, Melakukan koordinasi dengan berbagai pihak terkait dalam menyiapkan kegiatan pemantauan dan evaluasi program MBG, Menghadiri rapat rutin Tim Koordinasi Strategis, mencatat progress dan tindak lanjut, Melakukan analisis terhadap data pemantauan dan evaluasi untuk mengidentifikasi tantangan implementasi, capaian program, serta peluang perbaikan', 'a. Memiliki gelar S2 di bidang ekonomi/ kebijakan publik/ gizi masyarakat/ statistik/ kesehatan masyarakat/ ekonomi pembangunan. Dibuktikan dengan ijazah. b. Memiliki pengalaman kerja minimal 4 tahun terkait intervensi gizi/ sosial/ ekonomi ketenagakerjaan/ kemiskinan/ pendidikan/ kesehatan masyarakat. Dibuktikan dengan surat keterangan kerja/surat referensi. c. Memiliki pengalaman kerja di project yang melibatkan pemerintah/ mitra pembangunan internasional/ LSM di bidang sosial/ ekonomi/ kesehatan/ pendidikan/ kesejahteraan sosial. Dibuktikan dengan surat pengalaman kerja/ kontrak kerja/ sertifikat. d. Memiliki pengalaman dalam penyusunan instrumen survei untuk evaluasi program sosial/ kesehatan/ pendidikan/ ekonomi/ kesejahteraan sosial. Dibuktikan dengan dokumen pendukung terkait instrumen survei/ hasil analisis artikel/ hasil publikasi (bisa berupa PDF dokumen/ tautan dokumen/ lainnya). e. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak. f. Memiliki pekerjaan sejenis terkait bidang pemantauan/ evaluasi/ monitoring/ manajemen data/ analisis data dibuktikan dengan kontrak kerja/ surat referensi/ sertifikat. g. Mempunyai status valid keterangan wajib pajak berdasarkan hasil konfirmasi status wajib pajak. h. Memiliki nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran. i. Konsultan merupakan Warga Negara Indonesia yang dibuktikan dengan identitas kewarganegaraan Indonesia sebagai Kartu Tanda Penduduk.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2770897);
