INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66480766', 66480766, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Pemeliharaan E-Farmakope', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 34000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 1, PT, @ 34000000 )', '1. Pemeliharaan E-Farmakope ( 1, PT, @ 34000000 );', 'Melaksanakan pemeliharaan e-Farmakope Indonesia dengan penyesuaian materi mengikuti perkembangan ilmu dan regulasi farmasi serta menjamin keamanan sistem dari ancaman siber. HASIL YANG DIHARAPKAN/OUTPUT 1. Terpeliharanya e-Farmakope Indonesia dengan penambahan substansi sesuai update terbaru pada Suplemen IV Farmakope Indonesia Edisi VI. 2. Tersedianya Laporan Akhir sebanyak 3 (tiga) rangkap dalam mendukung pelaksanaan pekerjaan Pemeliharaan e-Farmakope Indonesia. 3. Tersediaanya file backup dan source terbaru beserta media penyimpanan. TENAGA KERJA a. Frontend developer: Bertanggung jawab dalam pengembangan dan pemeliharaan antarmuka pengguna (User Interface/UI) aplikasi agar mudah digunakan, konsisten, dan sesuai dengan kebutuhan sistem. b. Backend developer: Bertanggung jawab atas pengembangan, pemeliharaan, dan keamanan sisi server aplikasi serta pengelolaan basis data agar sistem berjalan stabil, aman, dan sesuai kebutuhan. c. Technical Writer: Bertanggung jawab dalam penyusunan, pengelolaan, dan penyajian dokumentasi teknis serta laporan resmi proyek secara sistematis, jelas, dan sesuai standar yang berlaku. LINGKUP PEKERJAAN a. Penyesuaian Materi: Update konten berdasarkan Farmakope Indonesia Ed. VI Suplemen IV. b. Perbaikan Konten: Perbaikan kesalahan tulis, rumus, simbol, dan hyperlink pada Ed. VI serta Suplemen I, II, dan III. c. Pemeliharaan Modul: Registrasi, User Management, Berita, Login Session, Pencarian, dan Log Aktivitas. d. Backup Database: Backup database secara berkala. e. Pelaporan: Penyusunan Laporan Akhir (Final Report)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2777499);
